#include "laser.hpp"
#include <laserdocklib/LaserdockDevice.h>
#include <laserdocklib/LaserdockDeviceManager.h>
#include <laserdocklib/LaserdockSample.h>
#include <array>
#include <algorithm>
#include <chrono>
#include <iostream>
#include <thread>
using namespace liquid;

static LaserdockSample toLaserDockSample(const Sample& sample,int brightness){LaserdockSample out{};uint16_t color=sample.lit?uint16_t(std::clamp(brightness,0,255)):0;out.rg=color|(color<<8);out.b=color;out.x=float_to_laserdock_xy(std::clamp(sample.xy.x,-1.f,1.f));out.y=float_to_laserdock_xy(std::clamp(sample.xy.y,-1.f,1.f));return out;}

void laserLoop(const Options&o,std::atomic<bool>&run,const Latest<CameraFrame>&camera,const Latest<OutputFrame>&output,Counters&counters,std::string&error,std::mutex&errorMutex,volatile std::sig_atomic_t&interrupted){try{LaserdockDevice* device=LaserdockDeviceManager::getInstance().get_next_available_device();if(!device)throw std::runtime_error("LaserDock not found");std::cout<<"LaserDock serial: "<<device->get_serial_number()<<'\n';device->disable_output();device->clear_ringbuffer();if(!device->set_dac_rate(30000))throw std::runtime_error("LaserDock set_dac_rate failed");uint32_t actualRate=0;if(!device->dac_rate(&actualRate))throw std::runtime_error("LaserDock dac_rate failed");std::cout<<"LaserDock DAC: "<<actualRate<<" pps\n";device->setFlipX(false);device->setFlipY(false);device->clear_ringbuffer();constexpr int PACKET=64;std::array<LaserdockSample,PACKET> packet{};Sample blank{{0,0},false};for(auto&s:packet)s=toLaserDockSample(blank,0);device->send_samples(packet.data(),PACKET);if(!device->enable_output())throw std::runtime_error("LaserDock enable_output failed");std::cout<<"Laser output ENABLED\n";std::shared_ptr<const OutputFrame> active;size_t index=0;V last{};ScanConfig scan{30000/o.fps,o.scale,o.flipX,o.flipY};while(run&&!interrupted){auto body=camera.get();auto now=Clock::now();bool cameraFresh=body&&body->valid&&seconds(body->captured,now)<.25;for(int j=0;j<PACKET;++j){if(!active||index>=active->samples.size()){active=output.get();index=0;}bool valid=cameraFresh&&active&&!active->samples.empty()&&seconds(active->made,now)<.25&&seconds(active->cameraTime,now)<.25;Sample s=valid?active->samples[index++]:Sample{last,false};if(valid&&s.lit&&body){V p=fromScan(s.xy,o.sim.extent,scan),previous=fromScan(last,o.sim.extent,scan);s.lit=clearSegment(previous,p,body->obstacle.sdf)&&norm(s.xy-last)<=.03f;}if(!finite(s.xy))s={last,false};if(!valid)index=active?active->samples.size():0;packet[j]=toLaserDockSample(s,o.brightness);last=s.xy;}if(!device->send_samples(packet.data(),PACKET)){++counters.laserErrors;bool recovered=false;for(int retry=0;retry<3;++retry){std::this_thread::sleep_for(std::chrono::milliseconds(2));if(device->send_samples(packet.data(),PACKET)){recovered=true;break;}}if(!recovered)throw std::runtime_error("LaserDock send_samples failed");}counters.submitted+=PACKET;}device->clear_ringbuffer();for(auto&s:packet)s=toLaserDockSample(blank,0);device->send_samples(packet.data(),PACKET);std::this_thread::sleep_for(std::chrono::milliseconds(10));device->disable_output();device->clear_ringbuffer();std::cout<<"Laser output DISABLED\n";}catch(const std::exception&e){++counters.laserErrors;std::lock_guard<std::mutex> lock(errorMutex);error=e.what();run=false;}}
